"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { ROLES, type OnboardingStepProps, type Role } from "../schema"

type Errors = { fullName?: string; role?: string }

function validateName(value: string): string | undefined {
  const name = value.trim()
  if (!name) return "Enter your full name."
  if (name.length < 2 || !/\p{L}/u.test(name)) return "Enter a valid name, at least 2 characters with letters."
  return undefined
}

const errorStyle = {
  margin: 0,
  marginBlockStart: "var(--atlas-spacing-1_5)",
  color: "var(--atlas-danger)",
  fontSize: "var(--atlas-text-body-sm)",
} as const

export function Profile({ data, patch, next }: OnboardingStepProps) {
  const [errors, setErrors] = useState<Errors>({})

  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    const found: Errors = {
      fullName: validateName(data.fullName),
      role: data.role ? undefined : "Choose the role that fits you best.",
    }
    setErrors(found)
    if (found.fullName) return document.getElementById("onboarding-name")?.focus()
    if (found.role) return document.getElementById(`onboarding-role-${ROLES[0].value}`)?.focus()
    patch({ fullName: data.fullName.trim() })
    next()
  }

  return (
    <form onSubmit={submit} noValidate
      style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div>
        <h2 style={{ margin: 0, fontSize: "var(--atlas-text-h2)", fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)" }}>
          Tell us about you
        </h2>
        <p style={{ margin: 0, marginBlockStart: "var(--atlas-spacing-1)", fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
          This helps us tailor your workspace.
        </p>
      </div>

      <div>
        <Label htmlFor="onboarding-name" required invalid={!!errors.fullName}>Full name</Label>
        <Input id="onboarding-name" autoComplete="name" value={data.fullName}
          onChange={(e) => {
            patch({ fullName: e.target.value })
            if (errors.fullName) setErrors((p) => ({ ...p, fullName: undefined }))
          }}
          onBlur={() => data.fullName && setErrors((p) => ({ ...p, fullName: validateName(data.fullName) }))}
          invalid={!!errors.fullName}
          aria-describedby={errors.fullName ? "onboarding-name-error" : undefined} />
        {errors.fullName && <p id="onboarding-name-error" role="alert" style={errorStyle}>{errors.fullName}</p>}
      </div>

      <div>
        <Label htmlFor="onboarding-role-group" required invalid={!!errors.role}>Role</Label>
        <RadioGroup id="onboarding-role-group" aria-label="Role" value={data.role} invalid={!!errors.role} required
          onValueChange={(v) => {
            patch({ role: v as Role })
            setErrors((p) => ({ ...p, role: undefined }))
          }}
          aria-describedby={errors.role ? "onboarding-role-error" : undefined}>
          {ROLES.map((r) => (
            <RadioGroupItem key={r.value} id={`onboarding-role-${r.value}`} value={r.value} label={r.label} invalid={!!errors.role} />
          ))}
        </RadioGroup>
        {errors.role && <p id="onboarding-role-error" role="alert" style={errorStyle}>{errors.role}</p>}
      </div>

      <Button type="submit" variant="primary" size="lg">Continue</Button>
    </form>
  )
}

